// 가정: 고정자산 모듈 연계는 본 시스템 내 fixed_asset 테이블 갱신으로 처리하고, 연계 결과 문구는 아래 상수로 둔다.
import { Controller, Put, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const LINK_DONE = '고정자산 모듈 연계 완료'; // 가정: 연계 결과 문구

function blank(v: unknown): boolean {
  return v === undefined || v === null || v === '';
}

@Controller('api/v1')
export class FnSfr02502Controller {
  @Put('/fixed-assets/:fixedAssetId/depreciation')
  async updateFixedAssetDepreciation(@Req() req: Request) {
    const user = currentUser(req);
    user.require('자산 담당자');
    const data = checks.inputOf(req.body);
    const fixedAssetId = req.params['fixedAssetId'];
    if (!/^\d+$/.test(fixedAssetId)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '고정자산 ID 형식이 올바르지 않습니다.');
    }
    const isDepreciable = data['isDepreciable'];
    if (typeof isDepreciable !== 'boolean') {
      throw new ApiError(400, 'VALIDATION_FAILED', '상각 여부를 지정해 주세요.');
    }
    const method = blank(data['depreciationMethod']) ? null : data['depreciationMethod'];
    if (method !== null && (typeof method !== 'string' || method.length > 50)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '상각 방법은 50자 이내 글자여야 합니다.');
    }
    const life = blank(data['usefulLifeYears']) ? null : data['usefulLifeYears'];
    if (life !== null && (typeof life !== 'number' || !Number.isInteger(life) || life <= 0)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '내용연수는 1 이상의 정수여야 합니다.');
    }
    const cost = blank(data['acquisitionCost']) ? null : data['acquisitionCost'];
    if (cost !== null && (typeof cost !== 'number' || !Number.isFinite(cost) || cost < 0)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '취득원가는 0 이상의 숫자여야 합니다.');
    }
    const start = blank(data['depreciationStartDate']) ? null : data['depreciationStartDate'];
    if (start !== null && (typeof start !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(start))) {
      throw new ApiError(400, 'VALIDATION_FAILED', '상각 시작일은 YYYY-MM-DD 형식이어야 합니다.');
    }
    if (isDepreciable) {
      const missing: string[] = [];
      if (method === null) missing.push('상각 방법');
      if (life === null) missing.push('내용연수');
      if (cost === null) missing.push('취득원가');
      if (start === null) missing.push('상각 시작일');
      if (missing.length > 0) {
        throw new ApiError(422, 'DEPRECIATION_INFO_MISSING', '상각 대상은 다음 항목을 입력해야 합니다: ' + missing.join(', '));
      }
    }
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT fixed_asset_id FROM fixed_asset WHERE fixed_asset_id = CAST(:id AS bigint)',
        { id: fixedAssetId },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'FIXED_ASSET_NOT_FOUND', '고정자산을 찾을 수 없습니다.');
      }
      if (start !== null) {
        const chk = await db.query(
          'SELECT (CAST(:start AS date) >= acquisition_date) AS "ok" FROM fixed_asset WHERE fixed_asset_id = CAST(:id AS bigint)',
          { id: fixedAssetId, start },
        );
        if (!chk[0]['ok']) {
          throw new ApiError(400, 'VALIDATION_FAILED', '상각 시작일은 취득일 이후여야 합니다.');
        }
      }
      const rows = await db.query(
        'UPDATE fixed_asset SET is_depreciable = :isDep, depreciation_method = :method, useful_life_years = CAST(:life AS integer), acquisition_cost = COALESCE(CAST(:cost AS numeric), acquisition_cost), depreciation_start_date = CAST(:start AS date), updated_at = now() WHERE fixed_asset_id = CAST(:id AS bigint) RETURNING fixed_asset_id AS "fixedAssetId", is_depreciable AS "isDepreciable", depreciation_method AS "depreciationMethod", useful_life_years AS "usefulLifeYears", acquisition_cost AS "acquisitionCost", to_char(depreciation_start_date, \'YYYY-MM-DD\') AS "depreciationStartDate"',
        { id: fixedAssetId, isDep: isDepreciable, method, life, cost, start },
      );
      return { ...rows[0], linkResult: LINK_DONE };
    });
  }
}

