import { useState } from 'react';
import { call, Badge, Num, DateText, Band, DataTable, Drawer, Form, Field, TextInput, NumberInput, DateInput, Select, LookupSelect, RefName, Tiles } from '../kit';
import type { PageProps, Row } from '../kit';

export default function FnSfr02502Page({ role, notify }: PageProps) {
  const [results, setResults] = useState<Row[]>([]);
  const [open, setOpen] = useState(false);
  const [assetId, setAssetId] = useState<number | string>('');
  const [isDepreciable, setIsDepreciable] = useState('');
  const [method, setMethod] = useState('');
  const [life, setLife] = useState<number | string>('');
  const [cost, setCost] = useState<number | string>('');
  const [start, setStart] = useState('');

  function openForm(row?: Row) {
    setAssetId((row?.fixedAssetId as number) ?? '');
    setIsDepreciable(row ? String(row.isDepreciable) : '');
    setMethod((row?.depreciationMethod as string) ?? '');
    setLife((row?.usefulLifeYears as number) ?? '');
    setCost((row?.acquisitionCost as number) ?? '');
    setStart((row?.depreciationStartDate as string) ?? '');
    setOpen(true);
  }

  async function submit() {
    if (assetId === '') throw new Error('자산을 선택해 주세요.');
    if (isDepreciable === '') throw new Error('상각 여부를 선택해 주세요.');
    if (isDepreciable === 'true') {
      const missing: string[] = [];
      if (method === '') missing.push('상각 방법');
      if (life === '') missing.push('내용연수');
      if (cost === '') missing.push('취득원가');
      if (start === '') missing.push('상각 시작일');
      if (missing.length > 0) throw new Error('상각 대상은 입력이 필요합니다: ' + missing.join(', '));
    }
    const body: Row = {
      isDepreciable: isDepreciable === 'true',
      depreciationMethod: method,
      usefulLifeYears: life,
      acquisitionCost: cost,
      depreciationStartDate: start,
    };
    const res = await call('PUT', `/fixed-assets/${assetId}/depreciation`, role, body);
    setResults((prev) => [res, ...prev.filter((r) => r.fixedAssetId !== res.fixedAssetId)]);
    setOpen(false);
    notify('상각정보를 저장하고 고정자산에 연계했습니다.');
  }

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>처리 건수</h2>
        <Tiles items={[['이번 화면 처리', <Num value={results.length} />]]} />
      </section>
      <section className="box span-8">
        <h2>상각 처리 결과</h2>
        <Band total={results.length}>
          <button onClick={() => openForm()}>상각정보 등록</button>
        </Band>
        <DataTable
          rows={results}
          empty="처리한 자산이 없습니다."
          columns={[
            { key: 'fixedAssetId', label: '고정자산', render: (r) => <RefName table="fixed_asset" role={role} value={r.fixedAssetId} /> },
            { key: 'isDepreciable', label: '상각 여부', render: (r) => <Badge value={r.isDepreciable ? '상각' : '비상각'} /> },
            { key: 'depreciationMethod', label: '상각 방법' },
            { key: 'usefulLifeYears', label: '내용연수', render: (r) => <Num value={r.usefulLifeYears} /> },
            { key: 'acquisitionCost', label: '취득원가', render: (r) => <Num value={r.acquisitionCost} /> },
            { key: 'depreciationStartDate', label: '상각 시작일', render: (r) => <DateText value={r.depreciationStartDate} /> },
            { key: 'linkResult', label: '고정자산 모듈 연계 결과' },
            { key: 'edit', label: '처리', render: (r) => <button onClick={() => openForm(r)}>수정</button> },
          ]}
        />
      </section>
      {open && (
        <Drawer title="자산 상각정보 등록" onClose={() => setOpen(false)}>
          <Form onSubmit={submit} submit="저장 및 연계">
            <Field label="고정자산 ID" required>
              <LookupSelect table="fixed_asset" role={role} value={assetId} onChange={setAssetId} />
            </Field>
            <Field label="상각 여부" required>
              <Select value={isDepreciable} onChange={setIsDepreciable} options={[['true', '상각'], ['false', '상각 안 함']]} />
            </Field>
            <Field label="상각 방법" required={isDepreciable === 'true'}>
              <TextInput value={method} onChange={setMethod} />
            </Field>
            <Field label="내용연수" required={isDepreciable === 'true'}>
              <NumberInput value={life} onChange={setLife} />
            </Field>
            <Field label="취득원가" required={isDepreciable === 'true'}>
              <NumberInput value={cost} onChange={setCost} />
            </Field>
            <Field label="상각 시작일" required={isDepreciable === 'true'}>
              <DateInput value={start} onChange={setStart} />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
